import { Connection, Transaction, ComputeBudgetProgram } from '@solana/web3.js';

/**
 * Подписывает, отправляет и ожидает подтверждения транзакции Solana
 * @param {Object} options - Параметры транзакции
 * @param {Transaction|string} options.transaction - Транзакция или сериализованная транзакция в base64
 * @param {string} options.rpcUrl - URL RPC-узла Solana (опционально)
 * @param {boolean} options.withPriority - Добавить инструкции для увеличения приоритета (опционально)
 * @param {number} options.priorityFee - Размер приоритетной комиссии в microLamports (по умолчанию 25000)
 * @param {number} options.computeUnits - Лимит вычислительных единиц (по умолчанию 200000)
 * @param {string} options.commitment - Уровень подтверждения (по умолчанию 'confirmed')
 * @returns {Promise<Object>} - Результат транзакции с подписью и подтверждением
 */
export async function signAndSendTransaction({
  transaction,
  rpcUrl = process.env.VUE_APP_SOLANA_RPC_URL || 'https://mainnet.helius-rpc.com/?api-key=75b3b14f-83e0-4eaa-8009-aa3a1d3f835c',
  withPriority = false,
  priorityFee = 25000,
  computeUnits = 200000,
  commitment = 'confirmed'
}) {
  try {
    // Создаем подключение к Solana
    const connection = new Connection(rpcUrl);
    
    // Получаем последний blockhash
    const { blockhash, lastValidBlockHeight } = await connection.getLatestBlockhash('finalized');
    console.log('Got blockhash:', { blockhash, lastValidBlockHeight });
    
    // Десериализуем транзакцию, если она передана в виде строки
    let tx;
    if (typeof transaction === 'string') {
      tx = Transaction.from(Buffer.from(transaction, 'base64'));
    } else {
      tx = transaction;
    }
    
    // Обновляем транзакцию с актуальным blockhash
    tx.recentBlockhash = blockhash;
    tx.lastValidBlockHeight = lastValidBlockHeight;
    
    // Добавляем инструкции для увеличения приоритета, если требуется
    if (withPriority) {
      tx.instructions.unshift(
        ComputeBudgetProgram.setComputeUnitLimit({ units: computeUnits }),
        ComputeBudgetProgram.setComputeUnitPrice({
          microLamports: priorityFee,
        })
      );
    }
    
    // Проверяем доступность Phantom
    if (!window.solana) {
      throw new Error('Phantom wallet not found');
    }
    
    // Подписываем транзакцию через Phantom
    console.log('Signing transaction...');
    const signedTransaction = await window.solana.signTransaction(tx);
    
    // Отправляем подписанную транзакцию
    console.log('Sending transaction...');
    const signature = await connection.sendRawTransaction(signedTransaction.serialize());
    console.log('Transaction sent with signature:', signature);
    
    // Ждем подтверждения транзакции
    console.log('Waiting for confirmation...');
    const confirmation = await connection.confirmTransaction({
      signature,
      blockhash,
      lastValidBlockHeight
    }, commitment);
    
    console.log('Transaction confirmation:', confirmation);
    
    // Возвращаем результат
    return {
      success: !confirmation.value.err,
      signature,
      signedTransaction: Buffer.from(signedTransaction.serialize()).toString('base64'),
      confirmation,
      error: confirmation.value.err
    };
  } catch (error) {
    console.error('Transaction error:', error);
    return {
      success: false,
      error: error.message || 'Unknown error'
    };
  }
}
